142. function secureWebContents(
143.   contents: WebContents,
144.   rendererUrl: string,
145.   isDevelopment: boolean,
146. ): void {
147.   contents.setWindowOpenHandler(({ url }) => {
148.     void openAllowedExternalUrl(url);
149.     return { action: "deny" };
150.   });
151.   contents.on("will-navigate", (event, url) => {
152.     if (isAllowedRendererNavigation(url, rendererUrl)) return;
153.     event.preventDefault();
154.     void openAllowedExternalUrl(url);
155.   });
156.   contents.on("will-attach-webview", (event) => {
157.     event.preventDefault();
158.   });
159.   contents.on("before-input-event", (event, input) => {
160.     if (
161.       !isDevelopment
162.       && input.type === "keyDown"
163.       && (
164.         input.key === "F12"
165.         || (
166.           input.control
167.           && input.shift
168.           && input.key.toLocaleLowerCase() === "i"
169.         )
170.       )
171.     ) {
172.       event.preventDefault();
173.     }
174.   });
175. }
