177. function configureDefaultSession(
178.   developmentUrl: string | undefined,
179. ): void {
180.   const defaultSession = session.defaultSession;
181.   defaultSession.setPermissionCheckHandler(() => false);
182.   defaultSession.setPermissionRequestHandler(
183.     (_webContents, _permission, callback) => callback(false),
184.   );
185.   defaultSession.webRequest.onBeforeRequest(
186.     REMOTE_REQUEST_FILTER,
187.     (details, callback) => {
188.       callback({
189.         cancel: !isAllowedRendererResource(details.url, developmentUrl),
190.       });
191.     },
192.   );
193.   defaultSession.webRequest.onHeadersReceived((details, callback) => {
194.     if (!details.url.startsWith(`${DESKTOP_APP_SCHEME}://`)) {
195.       callback({ responseHeaders: details.responseHeaders });
196.       return;
197.     }
198.     callback({
199.       responseHeaders: {
200.         ...details.responseHeaders,
201.         "Content-Security-Policy": [createContentSecurityPolicy()],
202.       },
203.     });
204.   });
205. }
