207. async function registerAppProtocol(): Promise<void> {
208.   const rendererRoot = join(app.getAppPath(), "dist");
209.   await protocol.handle(DESKTOP_APP_SCHEME, async (request) => {
210.     const assetPath = resolveAppAssetPath(request.url, rendererRoot);
211.     if (!assetPath || request.method !== "GET") {
212.       return new Response("Not found", { status: 404 });
213.     }
214.     try {
215.       return await net.fetch(pathToFileURL(assetPath).toString());
216.     } catch (error) {
217.       reportDesktopError(`Failed to load ${request.url}`, error);
218.       return new Response("Not found", { status: 404 });
219.     }
220.   });
221. }
