223. async function createMainWindow(
224.   developmentUrl: string | undefined,
225. ): Promise<void> {
226.   const isDevelopment = developmentUrl !== undefined;
227.   const preloadPath = join(import.meta.dirname, "preload.cjs");
228.   const window = new BrowserWindow(
229.     createDesktopWindowOptions(preloadPath, isDevelopment),
230.   );
231.   mainWindow = window;
232.   const rendererUrl = developmentUrl ?? DESKTOP_APP_URL;
233.   secureWebContents(window.webContents, rendererUrl, isDevelopment);
234. 
235.   window.on("enter-full-screen", () => sendFullscreenState(window));
236.   window.on("leave-full-screen", () => sendFullscreenState(window));
237.   window.on("unresponsive", () => {
238.     reportDesktopError("Renderer became unresponsive", rendererUrl);
239.   });
240.   window.on("closed", () => {
241.     if (mainWindow === window) mainWindow = null;
242.   });
243.   window.webContents.on(
244.     "render-process-gone",
245.     (_event, details) => reportDesktopError(
246.       `Renderer process exited (${details.reason})`,
247.       `exitCode=${details.exitCode}`,
248.     ),
249.   );
250.   window.webContents.on(
251.     "did-fail-load",
252.     (_event, errorCode, errorDescription, validatedUrl) => {
253.       reportDesktopError(
254.         `Failed to load renderer ${validatedUrl}`,
255.         `${errorCode}: ${errorDescription}`,
256.       );
257.     },
258.   );
259.   window.once("ready-to-show", () => window.show());
260.   await window.loadURL(rendererUrl);
261. }
