124. /** Initialize the debug command input listener (called once on startup). */
125. export function initDebugCommandInput(): void {
126.   const input = document.getElementById("debug-cmd") as HTMLInputElement | null;
127.   if (!input) return;
128.   input.addEventListener("keydown", (e) => {
129.     e.stopPropagation(); // prevent Phaser from capturing keys while typing
130.     if (e.key === "Enter") {
131.       const raw = input.value.trim();
132.       input.value = "";
133.       if (!raw.startsWith("/")) {
134.         debugPanelLog(`Unknown command: ${raw}. For a list of commands try /help. Commands start with /`, true);
135.         return;
136.       }
137.       if (!_debug) {
138.         debugPanelLog("Debug mode is off!", true);
139.         return;
140.       }
141.       const parts = raw.slice(1).split(/\s+/);
142.       const cmd = parts[0].toLowerCase();
143.       const args = parts.slice(1).join(" ");
144.       if (_debugCommandHandler) {
145.         _debugCommandHandler(cmd, args);
146.       } else {
147.         debugPanelLog(`No active command handler.`, true);
148.       }
149.     }
150.   });
151.   // Prevent Phaser from stealing focus events  
152.   input.addEventListener("keyup", (e) => e.stopPropagation());
153.   input.addEventListener("keypress", (e) => e.stopPropagation());
154. }
