26. export const DESKTOP_LOG_FILE_NAME = "2dnd.log";
27. export const DESKTOP_PREVIOUS_LOG_FILE_NAME = "2dnd.previous.log";
28. export const DEFAULT_DESKTOP_LOG_MAX_BYTES = 1024 * 1024;
29. const MAX_LOG_MESSAGE_LENGTH = 8_192;
30. 
31. function normalizeLogMessage(message: string): string {
32.   return message
33.     .replace(/\r\n?|\n/g, "\\n")
34.     .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "?")
35.     .slice(0, MAX_LOG_MESSAGE_LENGTH);
36. }
37. 
38. export function createDesktopLogger(
39.   directory: string,
40.   options: DesktopLoggerOptions = {},
41. ): DesktopLogger {
42.   const maxBytes = options.maxBytes ?? DEFAULT_DESKTOP_LOG_MAX_BYTES;
43.   if (!Number.isInteger(maxBytes) || maxBytes < 128) {
44.     throw new Error("Desktop log maxBytes must be an integer of at least 128");
45.   }
46.   const now = options.now ?? (() => new Date());
47.   const filePath = join(directory, DESKTOP_LOG_FILE_NAME);
48.   const previousFilePath = join(directory, DESKTOP_PREVIOUS_LOG_FILE_NAME);
49.   mkdirSync(directory, { recursive: true });
50. 
51.   const write = (level: DesktopLogLevel, message: string): void => {
52.     const line = `${now().toISOString()} [${level}] ${
53.       normalizeLogMessage(message)
54.     }\n`;
55.     const lineBytes = Buffer.byteLength(line);
56.     try {
57.       const currentBytes = existsSync(filePath) ? statSync(filePath).size : 0;
58.       if (currentBytes > 0 && currentBytes + lineBytes > maxBytes) {
59.         rmSync(previousFilePath, { force: true });
60.         renameSync(filePath, previousFilePath);
61.       }
62.       appendFileSync(filePath, line, { encoding: "utf8", mode: 0o600 });
63.     } catch (error) {
64.       process.stderr.write(
65.         `[desktop] Failed to write log: ${
66.           error instanceof Error ? error.message : String(error)
67.         }\n`,
68.       );
69.     }
70.   };
71. 
72.   return {
73.     filePath,
74.     previousFilePath,
75.     info: (message: string): void => write("INFO", message),
76.     warn: (message: string): void => write("WARN", message),
77.     error: (message: string): void => write("ERROR", message),
78.   };
