7. export const DESKTOP_APP_HOST = "2dnd";
8. export const DESKTOP_APP_SCHEME = "app";
9. export const DESKTOP_APP_URL = `${DESKTOP_APP_SCHEME}://${DESKTOP_APP_HOST}/index.html`;
10. 
11. const ALLOWED_EXTERNAL_DESTINATIONS = Object.freeze([
12.   {
13.     origin: "https://github.com",
14.     pathPrefix: "/mbianchidev/2dnd",
15.   },
16.   {
17.     origin: "https://mbianchidev.github.io",
18.     pathPrefix: "/2dnd",
19.   },
20. ]);
