22. function parseUrl(value: string): URL | null {
23.   try {
24.     return new URL(value);
25.   } catch {
26.     return null;
27.   }
28. }
29. 
30. function hasSafeCredentials(url: URL): boolean {
31.   return url.username.length === 0 && url.password.length === 0;
32. }
33. 
34. export function isAllowedExternalUrl(value: string): boolean {
35.   const url = parseUrl(value);
36.   if (!url || url.protocol !== "https:" || !hasSafeCredentials(url)) {
37.     return false;
38.   }
39.   return ALLOWED_EXTERNAL_DESTINATIONS.some(
40.     ({ origin, pathPrefix }) => url.origin === origin
41.       && (
42.         url.pathname === pathPrefix
43.         || url.pathname.startsWith(`${pathPrefix}/`)
44.       ),
45.   );
46. }
47. 
48. export function isAllowedDevelopmentUrl(value: string): boolean {
49.   const url = parseUrl(value);
50.   if (!url || url.protocol !== "http:" || !hasSafeCredentials(url)) {
51.     return false;
52.   }
53.   if (url.hostname !== "127.0.0.1" && url.hostname !== "localhost") {
54.     return false;
55.   }
56.   const port = Number.parseInt(url.port, 10);
57.   return Number.isInteger(port) && port >= 1 && port <= 65_535;
58. }
59. 
60. export function isAllowedRendererNavigation(
61.   value: string,
62.   rendererUrl: string,
63. ): boolean {
64.   const target = parseUrl(value);
65.   const renderer = parseUrl(rendererUrl);
66.   if (!target || !renderer || !hasSafeCredentials(target)) return false;
67.   return target.protocol === renderer.protocol
68.     && target.hostname === renderer.hostname
69.     && target.port === renderer.port;
70. }
71. 
72. export function isAllowedRendererResource(
73.   value: string,
74.   developmentUrl?: string,
75. ): boolean {
76.   const target = parseUrl(value);
77.   if (!target || !hasSafeCredentials(target)) return false;
78.   if (target.protocol === `${DESKTOP_APP_SCHEME}:`) {
79.     return target.hostname === DESKTOP_APP_HOST;
80.   }
81.   if (!developmentUrl || !isAllowedDevelopmentUrl(developmentUrl)) {
82.     return false;
83.   }
84.   const development = new URL(developmentUrl);
85.   const allowedProtocols = development.protocol === "https:"
86.     ? ["https:", "wss:"]
87.     : ["http:", "ws:"];
88.   return allowedProtocols.includes(target.protocol)
89.     && target.hostname === development.hostname
90.     && target.port === development.port;
91. }
